# Get the list of all pins in the design
set all_pins [get_pins -of_objects [get_cells -hierarchical *] -filter "DIRECTION != none"]

# Separate pins by direction
set input_pins [list]
set output_pins [list]
set inout_pins [list]

foreach pin $all_pins {
    set direction [get_property DIRECTION $pin]
    if {$direction == "input"} {
        lappend input_pins $pin
    } elseif {$direction == "output"} {
        lappend output_pins $pin
    } elseif {$direction == "inout"} {
        lappend inout_pins $pin
    }
}

# Set constraints for input pins on the left edge
if {[llength $input_pins] > 0} {
    set_io_pin_constraint -direction input -pin_names $input_pins -region left:*
}

# Set constraints for output pins on the right edge
if {[llength $output_pins] > 0} {
    set_io_pin_constraint -direction output -pin_names $output_pins -region right:*
}

# Handle inout pins if any exist (placing them on top/bottom as per general convention if not specified, 
# but task says "every input pin is on the left edge and every output pin is on the right edge". 
# Inout pins are not mentioned. We will place them on top/bottom arbitrarily or leave them. 
# However, place_pins needs constraints for all pins. Let's place inout on top/bottom.
if {[llength $inout_pins] > 0} {
    set_io_pin_constraint -direction inout -pin_names $inout_pins -region top:*
}

# Place the pins
# Metal3 for horizontal (left/right edges usually imply vertical placement of the pin shape, so horizontal tracks? 
# Wait. 
# Left/Right edges: The pin is on the vertical boundary. The metal strip connecting to the pin is typically horizontal (Metal3 in platform flow defaults). 
# Top/Bottom edges: The pin is on the horizontal boundary. The metal strip connecting to the pin is typically vertical (Metal2 in platform flow defaults).
# The task says: "metal3 for pins on the left/right edges and metal2 for pins on the top/bottom edges".
# place_pins -hor_layers metal3 -ver_layers metal2
# This means:
# - Pins placed on vertical boundaries (left/right) will use Metal3 for their horizontal extension.
# - Pins placed on horizontal boundaries (top/bottom) will use Metal2 for their vertical extension.

place_pins \
    -hor_layers metal3 \
    -ver_layers metal2

# Get the list of all pins in the design
# Use get_ports to get the top-level IO ports, which is more direct for IO pin placement
set all_ports [get_ports]

set input_pins [list]
set output_pins [list]
set inout_pins [list]

foreach port $all_ports {
    set direction [get_property DIRECTION $port]
    if {$direction == "input"} {
        lappend input_pins $port
    } elseif {$direction == "output"} {
        lappend output_pins $port
    } elseif {$direction == "inout"} {
        lappend inout_pins $port
    }
}

# Set constraints for input pins on the left edge
if {[llength $input_pins] > 0} {
    set_io_pin_constraint -direction input -pin_names $input_pins -region left:*
}

# Set constraints for output pins on the right edge
if {[llength $output_pins] > 0} {
    set_io_pin_constraint -direction output -pin_names $output_pins -region right:*
}

# Handle inout pins if any exist
if {[llength $inout_pins] > 0} {
    set_io_pin_constraint -direction inout -pin_names $inout_pins -region top:*
}

# Place the pins
# Metal3 for horizontal (left/right edges) and Metal2 for vertical (top/bottom edges)
# The task specifies: metal3 for pins on left/right, metal2 for pins on top/bottom
# In OpenROAD place_pins:
# -hor_layers: layers used for pins on vertical boundaries (left/right) -> metal3
# -ver_layers: layers used for pins on horizontal boundaries (top/bottom) -> metal2
place_pins \
    -hor_layers metal3 \
    -ver_layers metal2

# Get the list of all ports in the design
# get_ports requires a pattern argument, so we use "*" to match all ports
set all_ports [get_ports *]

set input_pins [list]
set output_pins [list]
set inout_pins [list]

foreach port $all_ports {
    set direction [get_property DIRECTION $port]
    if {$direction == "input"} {
        lappend input_pins $port
    } elseif {$direction == "output"} {
        lappend output_pins $port
    } elseif {$direction == "inout"} {
        lappend inout_pins $port
    }
}

# Set constraints for input pins on the left edge
if {[llength $input_pins] > 0} {
    set_io_pin_constraint -direction input -pin_names $input_pins -region left:*
}

# Set constraints for output pins on the right edge
if {[llength $output_pins] > 0} {
    set_io_pin_constraint -direction output -pin_names $output_pins -region right:*
}

# Handle inout pins if any exist
if {[llength $inout_pins] > 0} {
    set_io_pin_constraint -direction inout -pin_names $inout_pins -region top:*
}

# Place the pins
# Metal3 for horizontal (left/right edges) and Metal2 for vertical (top/bottom edges)
# The task specifies: metal3 for pins on left/right, metal2 for pins on top/bottom
# In OpenROAD place_pins:
# -hor_layers: layers used for pins on vertical boundaries (left/right) -> metal3
# -ver_layers: layers used for pins on horizontal boundaries (top/bottom) -> metal2
place_pins \
    -hor_layers metal3 \
    -ver_layers metal2

# Get the list of all ports in the design
# get_ports requires a pattern argument, so we use "*" to match all ports
set all_ports [get_ports *]

set input_pins [list]
set output_pins [list]
set inout_pins [list]

foreach port $all_ports {
    # Use -object_type port when getting property from a port object
    set direction [get_property -object_type port DIRECTION $port]
    if {$direction == "input"} {
        lappend input_pins $port
    } elseif {$direction == "output"} {
        lappend output_pins $port
    } elseif {$direction == "inout"} {
        lappend inout_pins $port
    }
}

# Set constraints for input pins on the left edge
if {[llength $input_pins] > 0} {
    set_io_pin_constraint -direction input -pin_names $input_pins -region left:*
}

# Set constraints for output pins on the right edge
if {[llength $output_pins] > 0} {
    set_io_pin_constraint -direction output -pin_names $output_pins -region right:*
}

# Handle inout pins if any exist
if {[llength $inout_pins] > 0} {
    set_io_pin_constraint -direction inout -pin_names $inout_pins -region top:*
}

# Place the pins
# Metal3 for horizontal (left/right edges) and Metal2 for vertical (top/bottom edges)
# The task specifies: metal3 for pins on left/right, metal2 for pins on top/bottom
# In OpenROAD place_pins:
# -hor_layers: layers used for pins on vertical boundaries (left/right) -> metal3
# -ver_layers: layers used for pins on horizontal boundaries (top/bottom) -> metal2
place_pins \
    -hor_layers metal3 \
    -ver_layers metal2

# Create the output directory if it doesn't exist
if {![file exists outputs]} {
    file mkdir outputs
}

set output_file "outputs/unloaded_nets.txt"
set stream [open $output_file "w"]

# Get all nets in the design
set all_nets [get_nets *]

foreach net $all_nets {
    # Get all pins connected to this net
    set pins [get_pins -of_object $net]

    if {[llength $pins] == 0} {
        continue
    }

    set has_driver 0
    set has_load 0

    foreach pin $pins {
        set obj_type [sta::object_type $pin]

        if {$obj_type == "Pin"} {
            # It's a cell pin
            # Check if it's a driver
            if {[$pin is_driver]} {
                set has_driver 1
            } else {
                # It's a load (cell input pin)
                set has_load 1
            }
        } elseif {$obj_type == "Port"} {
            # It's a top-level port
            # Check if it's an output port (which acts as a load for the net)
            if {[sta::port_direction $pin] == "output"} {
                set has_load 1
            } else {
                # Input port acts as a driver
                set has_driver 1
            }
        }
    }

    # If the net has a driver but no loads, it's an unloaded net
    if {$has_driver && !$has_load} {
        # Find the driver instance and pin for output format
        set driver_info ""
        foreach pin $pins {
            set obj_type [sta::object_type $pin]
            if {$obj_type == "Pin"} {
                if {[$pin is_driver]} {
                    set driver_info [get_full_name $pin]
                    break
                }
            } elseif {$obj_type == "Port"} {
                if {[sta::port_direction $pin] == "output"} {
                    # This shouldn't happen if has_load is false, but just in case
                    set driver_info [get_full_name $pin]
                    break
                }
            }
        }

        # Format: <net_name> <driver_instance>/<driver_pin>
        # The driver_info is already in full name format like "inst_name/pin_name"
        puts $stream "$net $driver_info"
    }
}

close $stream
